1	import fsSync, { createReadStream } from 'fs';
2	import fs from 'fs/promises';
3	import path from 'path';
4	import readline from 'readline';
5	
6	import { getEnvString } from '../envars';
7	import logger from '../logger';
8	import { getConfigDirectoryPath } from './config/manage';
9	
10	export interface LogFileInfo {
11	  name: string;
12	  path: string;
13	  mtime: Date;
14	  type: 'debug' | 'error';
15	  size: number;
16	}
17	
18	/**
19	 * Gets the log directory path, respecting PROMPTFOO_LOG_DIR environment variable
20	 */
21	export function getLogDirectory(): string {
22	  const configDir = getConfigDirectoryPath(true);
23	  const customLogDir = getEnvString('PROMPTFOO_LOG_DIR');
24	  return customLogDir ? path.resolve(customLogDir) : path.join(configDir, 'logs');
25	}
26	
27	/**
28	 * Gets all log files from the logs directory, sorted by modification time (newest first)
29	 * @param type - Filter by log type: 'debug', 'error', or 'all'
30	 */
31	export async function getLogFiles(type: 'debug' | 'error' | 'all' = 'all'): Promise<LogFileInfo[]> {
32	  const logDir = getLogDirectory();
33	
34	  try {
35	    await fs.access(logDir);
36	  } catch {
37	    return [];
38	  }
39	
40	  try {
41	    const files = await fs.readdir(logDir);
42	    const logFiles: LogFileInfo[] = [];
43	
44	    for (const file of files) {
45	      if (!file.startsWith('promptfoo-') || !file.endsWith('.log')) {
46	        continue;
47	      }
48	      if (type !== 'all' && !file.includes(`-${type}-`)) {
49	        continue;
50	      }
51	
52	      const filePath = path.join(logDir, file);
53	      try {
54	        const stats = await fs.stat(filePath);
55	        const logType: 'debug' | 'error' = file.includes('-error-') ? 'error' : 'debug';
56	        logFiles.push({
57	          name: file,
58	          path: filePath,
59	          mtime: stats.mtime,
60	          type: logType,
61	          size: stats.size,
62	        });
63	      } catch {
64	        // Skip files we can't stat
65	        continue;
66	      }
67	    }
68	
69	    return logFiles.sort((a, b) => b.mtime.getTime() - a.mtime.getTime());
70	  } catch (error) {
71	    logger.error(`Error reading log directory: ${error}`);
72	    return [];
73	  }
74	}
75	
76	/**
77	 * Synchronous version of getLogFiles for use in contexts where async is not possible
78	 * @deprecated Use the async getLogFiles when possible
79	 */
80	export function getLogFilesSync(type: 'debug' | 'error' | 'all' = 'all'): LogFileInfo[] {
81	  const logDir = getLogDirectory();
82	
83	  if (!fsSync.existsSync(logDir)) {
84	    return [];
85	  }
86	
87	  try {
88	    return fsSync
89	      .readdirSync(logDir)
90	      .filter((file) => {
91	        if (!file.startsWith('promptfoo-') || !file.endsWith('.log')) {
92	          return false;
93	        }
94	        if (type === 'all') {
95	          return true;
96	        }
97	        return file.includes(`-${type}-`);
98	      })
99	      .map((file): LogFileInfo => {
100	        const filePath = path.join(logDir, file);
101	        const stats = fsSync.statSync(filePath);
102	        const logType: 'debug' | 'error' = file.includes('-error-') ? 'error' : 'debug';
103	        return {
104	          name: file,
105	          path: filePath,
106	          mtime: stats.mtime,
107	          type: logType,
108	          size: stats.size,
109	        };
110	      })
111	      .sort((a, b) => b.mtime.getTime() - a.mtime.getTime());
112	  } catch (error) {
113	    logger.error(`Error reading log directory: ${error}`);
114	    return [];
115	  }
116	}
