159	/**
160	 * Reads the last N lines from a file using streaming (memory efficient).
161	 * For small files (<1MB), reads the entire file and slices.
162	 * For large files, streams line by line keeping only the last N.
163	 */
164	export async function readLastLines(filePath: string, lineCount: number): Promise<string[]> {
165	  const stats = await fs.stat(filePath);
166	
167	  // For small files, just read the whole thing - it's faster
168	  const ONE_MB = 1024 * 1024;
169	  if (stats.size < ONE_MB) {
170	    const content = await fs.readFile(filePath, 'utf-8');
171	    const allLines = content.split('\n');
172	    // Remove trailing empty line if present
173	    if (allLines.length > 0 && allLines[allLines.length - 1] === '') {
174	      allLines.pop();
175	    }
176	    return allLines.slice(-lineCount);
177	  }
178	
179	  // For large files, stream and keep only the last N lines
180	  const lines: string[] = [];
181	  const rl = readline.createInterface({
182	    input: createReadStream(filePath, { encoding: 'utf-8' }),
183	    crlfDelay: Infinity,
184	  });
185	
186	  for await (const line of rl) {
187	    lines.push(line);
188	    if (lines.length > lineCount) {
189	      lines.shift();
190	    }
191	  }
192	
193	  return lines;
194	}
195	
196	/**
197	 * Reads the first N lines from a file using streaming (memory efficient).
198	 * Stops reading as soon as N lines are collected.
199	 */
200	export async function readFirstLines(filePath: string, lineCount: number): Promise<string[]> {
201	  const lines: string[] = [];
202	  const rl = readline.createInterface({
203	    input: createReadStream(filePath, { encoding: 'utf-8' }),
204	    crlfDelay: Infinity,
205	  });
206	
207	  for await (const line of rl) {
208	    lines.push(line);
209	    if (lines.length >= lineCount) {
210	      rl.close();
211	      break;
212	    }
213	  }
214	
215	  return lines;
216	}
