91	 *
92	 * @param cacheKey - The cache key to look up
93	 * @param providerName - Provider name for logging (e.g., 'OpenAI Video', 'Azure Video')
94	 * @returns The video storage key if cached and exists, null otherwise
95	 */
96	export async function checkVideoCache(
97	  cacheKey: string,
98	  providerName: string = 'Video',
99	): Promise<string | null> {
100	  const mappingPath = getCacheMappingPath(cacheKey);
101	
102	  try {
103	    const mappingData = await fsPromises.readFile(mappingPath, 'utf8');
104	    const mapping: VideoCacheMapping = JSON.parse(mappingData);
105	    // Verify the referenced video file still exists in storage
106	    if (mapping.videoKey) {
107	      const storage = getMediaStorage();
108	      if (await storage.exists(mapping.videoKey)) {
109	        return mapping.videoKey;
110	      }
111	    }
112	  } catch (err: unknown) {
113	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
114	      return null;
115	    }
116	    // Mapping file corrupted, treat as cache miss
117	    logger.debug(`[${providerName}] Cache mapping read failed: ${err}`);
118	  }
119	
120	  return null;
121	}
