82	/**
83	 * Reads entire file content, with warning for large files
84	 */
85	async function readFileContent(filePath: string): Promise<string[]> {
86	  const stats = await fs.stat(filePath);
87	
88	  // Warn about large files
89	  const ONE_MB = 1024 * 1024;
90	  if (stats.size > ONE_MB) {
91	    logger.warn(dedent`
92	      Log file is large (${formatFileSize(stats.size)}).
93	      Consider using ${chalk.cyan('-n <lines>')} to limit output.
94	    `);
95	  }
96	
97	  const content = await fs.readFile(filePath, 'utf-8');
98	  const lines = content.split('\n');
99	
100	  // Remove trailing empty line if present
101	  if (lines[lines.length - 1] === '') {
102	    lines.pop();
103	  }
104	
105	  return lines;
106	}
