108	/**
109	 * Prints log file content to console with optional filtering
110	 */
111	async function printLogContent(logPath: string, options: PrintOptions): Promise<void> {
112	  const stats = await fs.stat(logPath);
113	
114	  if (stats.size === 0) {
115	    logger.info(chalk.gray('Log file is empty.'));
116	    return;
117	  }
118	
119	  let lines: string[];
120	
121	  // Use streaming for tail/head operations on large files
122	  if (options.lines) {
123	    lines = await readLastLines(logPath, options.lines);
124	  } else if (options.head) {
125	    lines = await readFirstLines(logPath, options.head);
126	  } else {
127	    lines = await readFileContent(logPath);
128	  }
129	
130	  // Apply grep filter if specified
131	  if (options.grep) {
132	    lines = lines.filter((line) => options.grep!.test(line));
133	
134	    if (lines.length === 0) {
135	      logger.info(chalk.gray(`No lines matching pattern found.`));
136	      return;
137	    }
138	  }
139	
140	  const output = highlightLogLines(lines, options.noColor);
141	  logger.info(output);
142	}
