  const mappingPath = getCacheMappingPath(cacheKey);
  fs.writeFileSync(mappingPath, JSON.stringify(mapping, null, 2), 'utf8');
  logger.debug(`[${providerName}] Stored cache mapping at ${mappingPath}`);
